// Some portions generated by Claude
export type SparqlTerm = {
  type: "uri" | "literal" | "bnode" | "typed-literal";
  value: string;
  datatype?: string;
  "xml:lang"?: string;
};

const SAFE_LANGUAGE = /^[A-Za-z]+(?:-[A-Za-z0-9]+)*$/;
const SAFE_SPARQL_IRI = /^[A-Za-z][A-Za-z0-9+.-]*:[^<>"{}|^`\\\s]+$/;

export function isSparqlTerm(value: unknown): value is SparqlTerm {
  if (!value || typeof value !== "object") return false;
  const record = value as Record<string, unknown>;
  if (
    record.type !== "uri" &&
    record.type !== "literal" &&
    record.type !== "typed-literal" &&
    record.type !== "bnode"
  ) {
    return false;
  }
  if (typeof record.value !== "string") return false;
  if (
    record.datatype !== undefined &&
    (typeof record.datatype !== "string" ||
      !SAFE_SPARQL_IRI.test(record.datatype))
  ) return false;
  if (
    record["xml:lang"] !== undefined &&
    (typeof record["xml:lang"] !== "string" ||
      !SAFE_LANGUAGE.test(record["xml:lang"]))
  ) {
    return false;
  }
  if (
    record.type === "uri" ||
    record.type === "bnode"
  ) {
    if (record.datatype !== undefined || record["xml:lang"] !== undefined) {
      return false;
    }
  }
  if (record.datatype !== undefined && record["xml:lang"] !== undefined) {
    return false;
  }
  if (
    record.type === "typed-literal" &&
    (typeof record.datatype !== "string" || !record.datatype)
  ) {
    return false;
  }
  return true;
}

export const INTERNAL_LITERAL_NODE_PREFIX = "__rdf_literal__:";
export const INTERNAL_BNODE_NODE_PREFIX = "__rdf_bnode__:";
const RDF_LANG_STRING =
  "http://www.w3.org/1999/02/22-rdf-syntax-ns#langString";


export function isSafeSparqlIri(value: string) {
  return SAFE_SPARQL_IRI.test(value);
}

function escapedSparqlString(value: string) {
  return value
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"')
    .replace(/\r/g, "\\r")
    .replace(/\n/g, "\\n");
}

export function sparqlNodeId(term: SparqlTerm) {
  if (term.type === "uri") return term.value;
  if (term.type === "bnode") {
    return `${INTERNAL_BNODE_NODE_PREFIX}${term.value}`;
  }
  const language = term["xml:lang"]?.trim().toLocaleLowerCase() ?? "";
  const datatype =
    language && term.datatype === RDF_LANG_STRING ? "" : term.datatype ?? "";
  return `${INTERNAL_LITERAL_NODE_PREFIX}${JSON.stringify({
    type: term.type,
    value: term.value,
    datatype,
    language,
  })}`;
}

export function sparqlTermFromNodeId(nodeId: string): SparqlTerm | undefined {
  if (nodeId.startsWith(INTERNAL_BNODE_NODE_PREFIX)) {
    return {
      type: "bnode",
      value: nodeId.slice(INTERNAL_BNODE_NODE_PREFIX.length),
    };
  }
  if (nodeId.startsWith(INTERNAL_LITERAL_NODE_PREFIX)) {
    try {
      const parsed: unknown = JSON.parse(
        nodeId.slice(INTERNAL_LITERAL_NODE_PREFIX.length),
      );
      if (!parsed || typeof parsed !== "object") return undefined;
      const record = parsed as Record<string, unknown>;
      if (
        (record.type !== "literal" && record.type !== "typed-literal") ||
        typeof record.value !== "string" ||
        (record.datatype !== "" && typeof record.datatype !== "string") ||
        (record.language !== "" && typeof record.language !== "string")
      ) {
        return undefined;
      }
      const term: SparqlTerm = {
        type: record.type,
        value: record.value,
      };
      if (record.datatype) term.datatype = record.datatype;
      if (record.language) term["xml:lang"] = record.language;
      return isSparqlTerm(term) ? term : undefined;
    } catch {
      return undefined;
    }
  }
  return isSafeSparqlIri(nodeId)
    ? { type: "uri", value: nodeId }
    : undefined;
}

/**
 * Convert a canonical graph node ID back into a safe SPARQL VALUES token.
 * Blank-node labels cannot be relied on across endpoint requests, so they are
 * intentionally omitted instead of generating a query with incorrect scope.
 */
export function sparqlFacetValueToken(nodeId: string): string | null {
  const term = sparqlTermFromNodeId(nodeId);
  if (!term) return null;
  if (term.type === "uri") return `<${term.value}>`;
  if (term.type === "bnode") return null;
  const value = `"${escapedSparqlString(term.value)}"`;
  if (term["xml:lang"] && SAFE_LANGUAGE.test(term["xml:lang"])) {
    return `${value}@${term["xml:lang"]}`;
  }
  if (term.datatype && isSafeSparqlIri(term.datatype)) {
    return `${value}^^<${term.datatype}>`;
  }
  return value;
}

export function sparqlTermValue(nodeId: string) {
  return sparqlTermFromNodeId(nodeId)?.value;
}
